head.b:skin:
/* ==========================================================================
   LEXATRIP ULTRA-LUXURY EXPERIENTIAL MASTER THEME (2026 EDITION)
   Solid Navy (#0F172A), Sunset Orange (#FF6B00), Amber (#FFA000)
   ========================================================================== */
:root {
  --primary: #FF6B00;
  --primary-dark: #E65100;
  --primary-light: #FFF5EB;
  --accent: #FFA000;
  --navy: #0F172A;
  --navy-light: #1E293B;
  --navy-dark: #090D16;
  --bg-page: #F8FAFC;
  --card-bg: #FFFFFF;
  --text-main: #1E293B;
  --text-muted: #64748B;
  --border: #E2E8F0;
  --radius-lg: 16px;
  --radius-md: 12px;
  --radius-sm: 8px;
  --shadow-sm: 0 2px 4px rgba(15, 23, 42, 0.05);
  --shadow-md: 0 8px 24px rgba(15, 23, 42, 0.08);
  --shadow-lg: 0 16px 36px rgba(255, 107, 0, 0.16);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  padding-bottom: 76px; /* space for sticky mobile bottom bar */
}

/* Top Header Layout Section */
#top-banner-ads {
  width: 100%;
}

/* Main Luxury Header */
.main-header {
  background: #FFFFFF;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: 0 4px 16px rgba(15, 23, 42, 0.04);
}
.header-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 12px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}

/* Brand Logo & Typography */
.brand-logo-link {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  flex-shrink: 0;
}
.brand-logo-circle {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #FFFFFF;
  border: 2px solid #FF6B00;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(255, 107, 0, 0.2);
  flex-shrink: 0;
}
.brand-logo-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.brand-text {
  display: flex;
  flex-direction: column;
}
.brand-name-row {
  display: flex;
  align-items: center;
  gap: 6px;
  line-height: 1.1;
}
.brand-word-lexa {
  font-family: 'Outfit', 'Inter', sans-serif;
  font-size: 26px;
  font-weight: 900;
  color: var(--navy);
  letter-spacing: 0.5px;
}
/* Official Dual-line / Outline Orange TRIP */
.brand-word-trip {
  font-family: 'Outfit', 'Inter', sans-serif;
  font-size: 26px;
  font-weight: 900;
  color: #FFFFFF;
  -webkit-text-stroke: 1.8px #FF6B00;
  letter-spacing: 2px;
  display: inline-block;
  text-shadow: 0 0 1px #FF6B00, 1px 1px 0px rgba(255, 107, 0, 0.35);
}
.brand-dest-badge {
  background: var(--navy);
  color: #FFA000;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  padding: 3px 8px;
  border-radius: 4px;
  margin-left: 4px;
  text-transform: uppercase;
}
.brand-tagline {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 2px;
  margin-top: 2px;
  text-transform: uppercase;
}

/* Header Quick Action Buttons */
.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.btn-header {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 700;
  padding: 8px 14px;
  border-radius: 20px;
  text-decoration: none;
  transition: all 0.2s ease;
  white-space: nowrap;
}
.btn-header-book {
  background: var(--primary);
  color: #FFFFFF;
  box-shadow: 0 2px 8px rgba(255, 107, 0, 0.3);
}
.btn-header-book:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
}
.btn-header-wa {
  background: #25D366;
  color: #FFFFFF;
}
.btn-header-wa:hover {
  background: #1EBE5B;
}
.btn-header-app {
  background: var(--navy);
  color: #FFFFFF;
}
.btn-header-app:hover {
  background: var(--navy-light);
}

/* Language Switcher Button */
.lang-switcher {
  position: relative;
  cursor: pointer;
  background: #F1F5F9;
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 6px 12px;
  font-size: 12px;
  font-weight: 700;
  color: var(--navy);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  user-select: none;
}
.lang-dropdown {
  display: none;
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 6px;
  background: #FFFFFF;
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.12);
  min-width: 140px;
  z-index: 1001;
  overflow: hidden;
}
.lang-dropdown a {
  display: block;
  padding: 8px 14px;
  font-size: 13px;
  color: var(--text-main);
  text-decoration: none;
}
.lang-dropdown a:hover, .lang-dropdown a.active {
  background: var(--primary-light);
  color: var(--primary);
  font-weight: 700;
}

/* Category Navigation Bar (Horizontally Scrollable) */
.category-nav-wrapper {
  background: #FFFFFF;
  border-bottom: 1px solid var(--border);
  position: relative;
  display: flex;
  align-items: center;
}
.category-nav-container {
  max-width: 1280px;
  margin: 0 auto;
  width: 100%;
  position: relative;
  display: flex;
  align-items: center;
}
.cat-nav-scroll-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: #FFFFFF;
  border: 1px solid var(--border);
  color: var(--navy);
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(0,0,0,0.1);
  z-index: 5;
  flex-shrink: 0;
  margin: 0 4px;
  font-weight: 900;
  user-select: none;
}
.cat-nav-scroll-btn:hover {
  background: var(--primary-light);
  color: var(--primary);
}
.category-nav-flex {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  padding: 10px 12px;
  white-space: nowrap;
  scrollbar-width: thin;
  scrollbar-color: #CBD5E1 transparent;
  flex-grow: 1;
}
.category-nav-flex::-webkit-scrollbar {
  height: 3px;
}
.category-nav-flex::-webkit-scrollbar-thumb {
  background: #CBD5E1;
  border-radius: 3px;
}
.cat-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #F8FAFC;
  color: var(--text-main);
  border: 1px solid var(--border);
  padding: 8px 16px;
  border-radius: 24px;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s ease;
  flex-shrink: 0;
}
.cat-pill:hover, .cat-pill.active {
  background: var(--navy);
  color: #FFFFFF;
  border-color: var(--navy);
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.15);
}
.cat-pill.active {
  background: var(--primary);
  border-color: var(--primary);
}

/* Compact Luxury Hero Section */
.hero-compact {
  background: linear-gradient(135deg, #090D16 0%, #0F172A 60%, #1E293B 100%);
  color: #FFFFFF;
  padding: 24px 20px;
  text-align: center;
  border-bottom: 2px solid var(--primary);
}
.hero-container {
  max-width: 900px;
  margin: 0 auto;
}
.hero-badge-pill {
  display: inline-block;
  background: rgba(255, 107, 0, 0.15);
  border: 1px solid rgba(255, 107, 0, 0.4);
  color: #FFA000;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.5px;
  padding: 4px 14px;
  border-radius: 20px;
  text-transform: uppercase;
  margin-bottom: 10px;
}
.hero-compact-title {
  font-family: 'Outfit', sans-serif;
  font-size: 26px;
  font-weight: 800;
  color: #FFFFFF;
  margin-bottom: 8px;
  line-height: 1.25;
}
.hero-compact-desc {
  font-size: 14px;
  color: #CBD5E1;
  line-height: 1.5;
  max-width: 780px;
  margin: 0 auto;
}

/* Main Content Layout */
.content-wrapper {
  max-width: 1280px;
  margin: 24px auto;
  padding: 0 16px;
}

/* 4:5 Vertical Aspect Ratio Post Card Grid */
.post-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 22px;
}
.post-card {
  background: #FFFFFF;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
  transition: all 0.25s ease;
  position: relative;
}
.post-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: #CBD5E1;
}

/* Strict 4:5 Media Container */
.card-media-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 5;
  background: #0F172A;
  overflow: hidden;
}
.card-media-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
  display: block;
}
.post-card:hover .card-media-img {
  transform: scale(1.05);
}

/* Card Badges */
.card-badge-cat {
  position: absolute;
  top: 12px;
  left: 12px;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(4px);
  color: #FFA000;
  font-size: 11px;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  z-index: 2;
}
.card-badge-discount {
  position: absolute;
  top: 12px;
  right: 12px;
  background: var(--primary);
  color: #FFFFFF;
  font-size: 11px;
  font-weight: 900;
  padding: 4px 10px;
  border-radius: 20px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.2);
  z-index: 2;
}

.card-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.card-title {
  font-family: 'Outfit', sans-serif;
  font-size: 17px;
  font-weight: 700;
  color: var(--navy);
  line-height: 1.35;
  margin-bottom: 8px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card-snippet {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.5;
  margin-bottom: 14px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  flex-grow: 1;
}
.card-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: auto;
}
.card-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 700;
  padding: 9px 12px;
  border-radius: 8px;
  text-decoration: none;
  text-align: center;
  transition: all 0.2s ease;
}
.card-btn-book {
  background: var(--navy);
  color: #FFFFFF;
}
.card-btn-book:hover {
  background: var(--primary);
}
.card-btn-wa {
  background: #E8F5E9;
  color: #1B5E20;
  border: 1px solid #C8E6C9;
}
.card-btn-wa:hover {
  background: #25D366;
  color: #FFFFFF;
}

/* Single Article View & In-Article Booking Engine */
.article-container {
  max-width: 860px;
  margin: 0 auto;
  background: #FFFFFF;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  box-shadow: var(--shadow-sm);
}
.article-category {
  color: var(--primary);
  font-size: 13px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 8px;
  display: block;
}
.article-title {
  font-family: 'Outfit', sans-serif;
  font-size: 30px;
  font-weight: 900;
  color: var(--navy);
  line-height: 1.25;
  margin-bottom: 14px;
}
.article-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  color: var(--text-muted);
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 24px;
  flex-wrap: wrap;
}
.author-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  color: var(--navy);
}
.author-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--primary);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 900;
}

/* Interactive Booking Engine Card */
.booking-engine-box {
  background: linear-gradient(135deg, #FFF5EB 0%, #FFFFFF 100%);
  border: 2px solid var(--primary);
  border-radius: var(--radius-md);
  padding: 24px;
  margin: 28px 0;
  box-shadow: var(--shadow-md);
}
.booking-box-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
  flex-wrap: wrap;
  gap: 8px;
}
.booking-box-title {
  font-family: 'Outfit', sans-serif;
  font-size: 20px;
  font-weight: 800;
  color: var(--navy);
  display: flex;
  align-items: center;
  gap: 8px;
}
.booking-box-tag {
  background: var(--primary);
  color: #FFFFFF;
  font-size: 11px;
  font-weight: 800;
  padding: 3px 10px;
  border-radius: 12px;
  text-transform: uppercase;
}
.booking-fields-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}
.booking-field label {
  display: block;
  font-size: 12px;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 6px;
}
.booking-field input, .booking-field select {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid #CBD5E1;
  border-radius: 8px;
  font-size: 13px;
  font-family: inherit;
  background: #FFFFFF;
  color: var(--navy);
}
.booking-engine-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.engine-btn {
  flex: 1;
  min-width: 180px;
  padding: 12px 18px;
  border-radius: 30px;
  font-size: 14px;
  font-weight: 800;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.2s ease;
}
.engine-btn-book {
  background: var(--primary);
  color: #FFFFFF;
  box-shadow: 0 4px 12px rgba(255, 107, 0, 0.3);
}
.engine-btn-book:hover {
  background: var(--primary-dark);
}
.engine-btn-wa {
  background: #25D366;
  color: #FFFFFF;
  box-shadow: 0 4px 12px rgba(37, 211, 102, 0.25);
}
.engine-btn-wa:hover {
  background: #1EBE5B;
}

/* Compact Sleek Footer */
.main-footer {
  background: #090D16;
  color: #CBD5E1;
  padding: 40px 20px 24px;
  border-top: 3px solid var(--primary);
}
.footer-container {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 28px;
}
.footer-brand-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.footer-brand-row {
  display: flex;
  align-items: center;
  gap: 12px;
}
.footer-desc {
  font-size: 13px;
  color: #94A3B8;
  max-width: 720px;
  line-height: 1.5;
}

/* Official Portals as Premium Pill Buttons */
.footer-portals-section {
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 20px;
}
.footer-heading {
  color: #FFA000;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin-bottom: 14px;
}
.footer-portal-buttons {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
}
.portal-btn {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 10px;
  transition: all 0.2s ease;
}
.portal-btn:hover {
  background: rgba(255, 107, 0, 0.15);
  border-color: var(--primary);
  transform: translateY(-2px);
}
.portal-btn-icon {
  font-size: 20px;
  flex-shrink: 0;
}
.portal-btn-info {
  display: flex;
  flex-direction: column;
}
.portal-btn-title {
  color: #FFFFFF;
  font-size: 13px;
  font-weight: 700;
}
.portal-btn-sub {
  color: #94A3B8;
  font-size: 11px;
}

/* 24/7 Helpline & Concierge Row */
.footer-support-section {
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 20px;
}
.footer-contact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 10px;
}
.contact-pill {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  padding: 10px 14px;
  text-decoration: none;
  color: #E2E8F0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  transition: all 0.2s ease;
}
.contact-pill:hover {
  border-color: var(--primary);
  background: rgba(255, 107, 0, 0.1);
}
.contact-pill span {
  font-size: 11px;
  color: #94A3B8;
}
.contact-pill strong {
  font-size: 13px;
  color: #FFA000;
}

/* Footer Legal & Copyright */
.footer-legal-bar {
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 18px;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}
.legal-links-row {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}
.legal-links-row a {
  color: #CBD5E1;
  font-size: 12px;
  font-weight: 600;
  text-decoration: none;
  transition: color 0.2s;
}
.legal-links-row a:hover {
  color: var(--primary);
  text-decoration: underline;
}
.legal-links-row .sep {
  color: #475569;
}
.copyright-text {
  font-size: 12px;
  color: #64748B;
}

/* =======================================================================
   LUXURY ULTRA-PREMIUM BOTTOM ACTION BAR (Animated & Eye-Catching)
   ======================================================================= */
.mobile-bottom-bar {
  display: grid;
  grid-template-columns: 1fr 1fr 1.35fr 1fr;
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  width: 92%;
  max-width: 580px;
  height: 72px;
  background: rgba(10, 15, 29, 0.96);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1.5px solid rgba(255, 107, 0, 0.45);
  border-radius: 22px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.55), 0 0 25px rgba(255, 107, 0, 0.22);
  z-index: 9999;
  padding: 6px 10px;
  gap: 8px;
  align-items: center;
  box-sizing: border-box;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.bar-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  text-decoration: none;
  font-size: 11px;
  font-weight: 700;
  height: 56px;
  border-radius: 14px;
  transition: transform 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
  position: relative;
  overflow: hidden;
}
.bar-btn:active {
  transform: scale(0.93);
}

/* Call Button */
.bar-btn-call {
  color: #F8FAFC;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
}
.bar-btn-call:hover {
  background: rgba(255, 255, 255, 0.12);
}
@keyframes phoneWiggle {
  0%, 75%, 100% { transform: rotate(0deg) scale(1); }
  80% { transform: rotate(-18deg) scale(1.15); }
  85% { transform: rotate(18deg) scale(1.15); }
  90% { transform: rotate(-12deg) scale(1.08); }
  95% { transform: rotate(10deg) scale(1.05); }
}
.icon-call-svg {
  animation: phoneWiggle 3.5s ease-in-out infinite;
  transform-origin: center;
}

/* WhatsApp Button */
.bar-btn-wa {
  color: #FFFFFF;
  background: rgba(37, 211, 102, 0.12);
  border: 1px solid rgba(37, 211, 102, 0.35);
}
.bar-btn-wa:hover {
  background: rgba(37, 211, 102, 0.22);
}
@keyframes waPulseGlow {
  0%, 100% {
    transform: scale(1);
    filter: drop-shadow(0 0 2px rgba(37, 211, 102, 0.4));
  }
  50% {
    transform: scale(1.12);
    filter: drop-shadow(0 0 10px rgba(37, 211, 102, 0.95));
  }
}
.icon-wa-svg {
  animation: waPulseGlow 2.6s ease-in-out infinite;
  transform-origin: center;
}
.online-indicator {
  position: absolute;
  top: 4px;
  right: 8px;
  width: 6px;
  height: 6px;
  background: #25D366;
  border-radius: 50%;
  box-shadow: 0 0 6px #25D366;
  animation: blinkIndicator 1.4s ease-in-out infinite;
}
@keyframes blinkIndicator {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.3; transform: scale(0.7); }
}

/* Book Now Button (Hero CTA) */
.bar-btn-book {
  color: #FFFFFF !important;
  background: linear-gradient(135deg, #FF6B00 0%, #FF9033 50%, #FF6B00 100%) !important;
  background-size: 200% 100% !important;
  border: 1.5px solid rgba(255, 255, 255, 0.4) !important;
  box-shadow: 0 4px 18px rgba(255, 107, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.4) !important;
  animation: shimmerSlide 3s linear infinite, bookFloat 2.8s ease-in-out infinite !important;
}
@keyframes shimmerSlide {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
@keyframes bookFloat {
  0%, 100% { transform: translateY(0); box-shadow: 0 4px 18px rgba(255, 107, 0, 0.55); }
  50% { transform: translateY(-3px); box-shadow: 0 8px 24px rgba(255, 107, 0, 0.85); }
}
.deal-tag {
  font-size: 8px;
  background: rgba(0, 0, 0, 0.35);
  padding: 1px 5px;
  border-radius: 6px;
  font-weight: 800;
  letter-spacing: 0.3px;
  margin-top: -1px;
}

/* Get App Button */
.bar-btn-app {
  color: #E2E8F0;
  background: rgba(99, 102, 241, 0.12);
  border: 1px solid rgba(99, 102, 241, 0.35);
}
.bar-btn-app:hover {
  background: rgba(99, 102, 241, 0.22);
}
@keyframes appDownloadSlide {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(3px); }
}
.app-download-arrow {
  animation: appDownloadSlide 1.8s ease-in-out infinite;
}

.bar-btn .bar-label {
  line-height: 1;
  font-size: 11px;
  letter-spacing: 0.2px;
}

@media (max-width: 768px) {
  .mobile-bottom-bar {
    width: 100%;
    max-width: 100%;
    left: 0;
    right: 0;
    bottom: 0;
    transform: none;
    border-radius: 0;
    border-left: none;
    border-right: none;
    border-bottom: none;
    padding: 6px 8px calc(6px + env(safe-area-inset-bottom, 0px));
    height: 68px;
    gap: 6px;
  }
}

/* Desktop Call Prompt Modal */
.call-modal-overlay {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  z-index: 10000;
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.call-modal-box {
  background: #FFFFFF;
  border-radius: var(--radius-lg);
  padding: 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 0 16px 40px rgba(0,0,0,0.25);
}

body.script:
//
  let allPostsData = [];
  let currentCategoryFilter = 'all';

  // Horizontal Scroll for Category Pills
  function scrollCatNav(offset) {
    const el = document.getElementById('categoryNav');
    if (el) el.scrollBy({ left: offset, behavior: 'smooth' });
  }

  // Call Action Handler
  function handleCallClick(e) {
    const isMobile = /Android|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    if (isMobile) {
      window.location.href = 'tel:+919079854982';
    } else {
      if (e) e.preventDefault();
      const modal = document.getElementById('callModal');
      if (modal) modal.style.display = 'flex';
    }
  }

  // Language Toggle
  function toggleLangMenu(e) {
    if (e) e.stopPropagation();
    const dd = document.getElementById('langDropdown');
    if (dd) dd.style.display = dd.style.display === 'block' ? 'none' : 'block';
  }
  document.addEventListener('click', () => {
    const dd = document.getElementById('langDropdown');
    if (dd) dd.style.display = 'none';
  });
  function selectLang(lang, e) {
    if (e) e.preventDefault();
    if (lang === 'hi') {
      window.location.href = 'https://translate.google.com/translate?sl=en&tl=hi&u=' + encodeURIComponent(window.location.href);
    } else {
      const dd = document.getElementById('langDropdown');
      if (dd) dd.style.display = 'none';
    }
  }

  // Dynamic Realistic Discount Generator
  function getPostDiscount(title, id) {
    const match = (title + '').match(/(\d{2})%\s*off/i);
    if (match) return match[1] + '% Off';
    const discounts = ['35% Off', '40% Off', '45% Off', '50% Off', '55% Off', '60% Off'];
    let hash = 0;
    const str = (title || '') + (id || '');
    for (let i = 0; i < str.length; i++) hash = (hash * 31 + str.charCodeAt(i)) >>> 0;
    return discounts[hash % discounts.length];
  }

  // Main Engine Runner
  async function loadLexaBlogContent() {
    const container = document.getElementById('lexa-dynamic-root');
    if (!container) return;

    const currentPath = window.location.pathname;
    const lowPath = currentPath.toLowerCase();

    // 1. Legal / Static Page Routing
    if (lowPath.includes('about-us')) {
      renderLegalStaticPage(container, "About Us - LexaTrip™ RAJASTHAN", "\n        <h2>Welcome to LexaTrip™ RAJASTHAN</h2>\n        <p><strong>LexaTrip™ Technologies Pvt. Ltd.</strong> is India's leading experiential luxury travel and hospitality network. LexaTrip™ RAJASTHAN is our dedicated official portal curating the finest 100% verified luxury stays, resorts, heritage properties, and bespoke tours in RAJASTHAN.</p>\n        \n        <h3>Our Core Philosophy: Book. Explore. Repeat.</h3>\n        <p>At LexaTrip, we believe true travel luxury combines authentic local culture with seamless, stress-free hospitality. Whether you are experiencing Grand Fort & Palace Royal Circuit, Desert Camps & Heritage, every LexaTrip partner property is physically inspected and audited for guest safety, premium hygiene, verified amenities, and world-class hospitality.</p>\n\n        <h3>Why Travelers Choose LexaTrip™ RAJASTHAN:</h3>\n        <ul>\n          <li><strong>100% Physically Verified Properties:</strong> Every hotel, luxury camp, and resort in RAJASTHAN is rigorously audited by our local destination concierges.</li>\n          <li><strong>Best Rate Guarantee:</strong> Direct hotelier partnerships give you up to 50-60% exclusive seasonal discounts with zero hidden charges.</li>\n          <li><strong>24/7 Dedicated Concierge Support:</strong> Priority assistance via phone (+91 90798 54982 / +91 90790 17880) and WhatsApp.</li>\n          <li><strong>Instant Confirmation &amp; Vouchers:</strong> Real-time booking access via <a href=\"https://bookings.lexatrip.com\" target=\"_blank\">bookings.lexatrip.com</a>.</li>\n        </ul>\n\n        <h3>Corporate Contact &amp; Portals</h3>\n        <p><strong>LexaTrip Technologies Private Limited</strong><br/>\n        Official Portals: <a href=\"https://bookings.lexatrip.com\">bookings.lexatrip.com</a> | <a href=\"https://www.lexatrip.com\">lexatrip.com</a> | <a href=\"https://www.lexatrip.in\">lexatrip.in</a><br/>\n        24/7 Helplines: <a href=\"tel:+919079854982\">+91 90798 54982</a>, <a href=\"tel:+919079017880\">+91 90790 17880</a><br/>\n        Official Email: <a href=\"mailto:infolexatrip@gmail.com\">infolexatrip@gmail.com</a></p>\n      ");
      return;
    }
    if (lowPath.includes('contact-us')) {
      renderLegalStaticPage(container, "Contact Us - LexaTrip™ RAJASTHAN", "\n        <h2>Get in Touch with LexaTrip™ RAJASTHAN Concierge</h2>\n        <p>Our dedicated 24/7 travel concierge and reservation desk is ready to assist you with tour planning, hotel reservations, package customization, and special requests for RAJASTHAN.</p>\n\n        <div style=\"display:grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap:16px; margin:24px 0;\">\n          <div style=\"background:#F8FAFC; border:1px solid #E2E8F0; border-radius:12px; padding:16px;\">\n            <h4 style=\"margin:0 0 8px; color:#FF6B00;\">📞 24/7 Helpline 1</h4>\n            <p style=\"margin:0; font-size:16px; font-weight:700;\"><a href=\"tel:+919079854982\" style=\"color:#0F172A; text-decoration:none;\">+91 90798 54982</a></p>\n            <small style=\"color:#64748B;\">Direct Call &amp; Booking Support</small>\n          </div>\n          <div style=\"background:#F8FAFC; border:1px solid #E2E8F0; border-radius:12px; padding:16px;\">\n            <h4 style=\"margin:0 0 8px; color:#FF6B00;\">📞 24/7 Helpline 2</h4>\n            <p style=\"margin:0; font-size:16px; font-weight:700;\"><a href=\"tel:+919079017880\" style=\"color:#0F172A; text-decoration:none;\">+91 90790 17880</a></p>\n            <small style=\"color:#64748B;\">Direct Line &amp; WhatsApp</small>\n          </div>\n          <div style=\"background:#F8FAFC; border:1px solid #E2E8F0; border-radius:12px; padding:16px;\">\n            <h4 style=\"margin:0 0 8px; color:#25D366;\">💬 Official WhatsApp Desk</h4>\n            <p style=\"margin:0; font-size:16px; font-weight:700;\"><a href=\"https://wa.me/919079854982?text=Hello%20LexaTrip,%20I%20would%20like%20to%20inquire%20about%20RAJASTHAN%20packages\" target=\"_blank\" style=\"color:#0F172A; text-decoration:none;\">Chat on WhatsApp</a></p>\n            <small style=\"color:#64748B;\">Instant Quotes &amp; Itineraries</small>\n          </div>\n          <div style=\"background:#F8FAFC; border:1px solid #E2E8F0; border-radius:12px; padding:16px;\">\n            <h4 style=\"margin:0 0 8px; color:#0F172A;\">✉️ Email Support</h4>\n            <p style=\"margin:0; font-size:16px; font-weight:700;\"><a href=\"mailto:infolexatrip@gmail.com\" style=\"color:#0F172A; text-decoration:none;\">infolexatrip@gmail.com</a></p>\n            <small style=\"color:#64748B;\">Official Inquiries &amp; Bookings</small>\n          </div>\n        </div>\n\n        <h3>Official Web Portals</h3>\n        <ul>\n          <li><strong>Online Reservations:</strong> <a href=\"https://bookings.lexatrip.com\" target=\"_blank\">bookings.lexatrip.com</a></li>\n          <li><strong>Main Website:</strong> <a href=\"https://www.lexatrip.com\" target=\"_blank\">lexatrip.com</a></li>\n          <li><strong>National Portal:</strong> <a href=\"https://www.lexatrip.in\" target=\"_blank\">lexatrip.in</a></li>\n          <li><strong>Mobile App:</strong> <a href=\"https://www.lexatrip.com/app\" target=\"_blank\">Download LexaTrip Mobile App</a></li>\n        </ul>\n      ");
      return;
    }
    if (lowPath.includes('privacy-policy')) {
      renderLegalStaticPage(container, "Privacy Policy - LexaTrip™ RAJASTHAN", "\n        <h2>Privacy Policy</h2>\n        <p><em>Last Updated: 2026 | LexaTrip™ Technologies Pvt. Ltd.</em></p>\n        \n        <p>At LexaTrip™ RAJASTHAN (accessible from https://lexatriprajasthan.blogspot.com, lexatrip.com, bookings.lexatrip.com, and lexatrip.in), the privacy of our visitors and guests is paramount. This Privacy Policy details the types of personal information collected, how it is used, and the security protocols employed to safeguard your data.</p>\n\n        <h3>1. Information We Collect</h3>\n        <p>When you browse our guides, submit an inquiry, or book travel packages through LexaTrip™ RAJASTHAN, we may collect the following details:</p>\n        <ul>\n          <li>Full Name, Contact Number, and Email Address</li>\n          <li>Travel Dates (Check-in / Check-out) and Number of Guests (Pax)</li>\n          <li>Selected Destination (RAJASTHAN), Hotel/Camp preference, and Tour requirements</li>\n          <li>Standard technical log data (IP address, browser type, device information) for security and analytical optimization</li>\n        </ul>\n\n        <h3>2. How We Use Your Information</h3>\n        <ul>\n          <li>To confirm hotel reservations, desert camp bookings, and safari vouchers in RAJASTHAN.</li>\n          <li>To provide real-time updates and customer support via WhatsApp, phone, or email.</li>\n          <li>To communicate exclusive discounts, promo codes, and special seasonal travel offers.</li>\n          <li>To prevent fraud, verify guest identity upon arrival, and maintain booking integrity.</li>\n        </ul>\n\n        <h3>3. 256-Bit SSL Data Security</h3>\n        <p>All sensitive communications, bookings, and customer interactions are encrypted using industry-standard 256-bit SSL encryption. We never sell, rent, or trade your personal data to unauthorized third parties.</p>\n\n        <h3>4. Third-Party Integrations</h3>\n        <p>We work with trusted partners including Google, Meta, verified payment gateways, and WhatsApp Business API to deliver seamless travel services in RAJASTHAN. These providers maintain strict data privacy compliance standards.</p>\n\n        <h3>5. Contact Our Data Protection Officer</h3>\n        <p>For any questions regarding our Privacy Policy or your personal data, please contact us at <a href=\"mailto:infolexatrip@gmail.com\">infolexatrip@gmail.com</a>.</p>\n      ");
      return;
    }
    if (lowPath.includes('terms-conditions') || lowPath.includes('terms')) {
      renderLegalStaticPage(container, "Terms & Conditions - LexaTrip™ RAJASTHAN", "\n        <h2>Terms and Conditions</h2>\n        <p><em>Last Updated: 2026 | LexaTrip™ Technologies Pvt. Ltd.</em></p>\n\n        <p>Please read these Terms and Conditions carefully before booking any tour packages, hotel stays, or activities in RAJASTHAN through LexaTrip™ websites, blogs, or mobile platforms.</p>\n\n        <h3>1. Booking and Confirmation</h3>\n        <ul>\n          <li>All reservations made through <a href=\"https://bookings.lexatrip.com\">bookings.lexatrip.com</a> or our WhatsApp concierge desk for RAJASTHAN are subject to availability and formal confirmation via booking voucher.</li>\n          <li>Promotional coupon codes (such as LEXA50ACTIVE or dynamic seasonal discounts) are valid only during specified promotional periods.</li>\n        </ul>\n\n        <h3>2. Check-in, Check-out &amp; Guest Verification</h3>\n        <ul>\n          <li>Standard check-in is 12:00 PM and check-out is 10:00 AM (or as designated by the specific resort/hotel in RAJASTHAN).</li>\n          <li>All Indian citizens must present government-approved photo ID (Aadhaar Card, Driving License, or Passport). Foreign nationals must present a valid Passport and Visa. Pan Cards are not accepted for hotel check-ins under local laws.</li>\n        </ul>\n\n        <h3>3. Cancellation and Refund Policy</h3>\n        <ul>\n          <li>Cancellations made 7 or more days prior to check-in date: 90% refund (10% processing fee).</li>\n          <li>Cancellations made 3 to 6 days prior to check-in: 50% refund.</li>\n          <li>Cancellations made within 48 hours of check-in or no-shows: Non-refundable.</li>\n        </ul>\n\n        <h3>4. Local Activities &amp; Tours</h3>\n        <p>Participation in local tours, safaris, and activities in RAJASTHAN (including Grand Fort & Palace Royal Circuit, Desert Camps & Heritage) is undertaken with certified partners adhering to safety regulations. Guests are advised to follow all safety briefings issued by local guides and pilots.</p>\n\n        <h3>5. Governing Law and Jurisdiction</h3>\n        <p>These terms and conditions are governed by and construed in accordance with the laws of India. Any disputes arising hereunder shall be subject to the exclusive jurisdiction of the competent courts in India.</p>\n      ");
      return;
    }

    // 2. Fetch Blogger JSON Feed
    try {
      const res = await fetch('/feeds/posts/default?alt=json&max-results=50');
      if (res.ok) {
        const data = await res.json();
        allPostsData = (data.feed && data.feed.entry) ? data.feed.entry : [];
      }
    } catch (e) {
      console.warn('Feed fetch error:', e);
    }

    // 3. Route: Single Post vs Grid
    const isSinglePost = currentPath.endsWith('.html') && !currentPath.includes('/p/');
    if (isSinglePost) {
      renderSingleArticle(container, currentPath);
    } else {
      renderPostGrid(container, currentCategoryFilter);
    }
  }

  // Real-Time Category Filtering
  function filterCategory(cat, event) {
    if (event) event.preventDefault();
    currentCategoryFilter = cat;

    document.querySelectorAll('.cat-pill').forEach(btn => {
      btn.classList.toggle('active', btn.getAttribute('onclick').includes("'" + cat + "'") || btn.getAttribute('onclick').includes('"' + cat + '"'));
    });

    const container = document.getElementById('lexa-dynamic-root');
    if (container) renderPostGrid(container, cat);
  }

  // Render 4:5 Card Grid
  function renderPostGrid(container, cat) {
    let filtered = allPostsData;
    if (cat !== 'all') {
      filtered = allPostsData.filter(entry => {
        const catList = (entry.category || []).map(c => (c.term || '').toLowerCase());
        const title = ((entry.title && entry.title.$t) || '').toLowerCase();
        const content = ((entry.content && entry.content.$t) || '').toLowerCase();
        const target = cat.toLowerCase();

        if (target === 'camp') return catList.some(c => c.includes('camp') || c.includes('tent') || c.includes('कैंप')) || title.includes('camp') || content.includes('camp');
        if (target === '5-star') return catList.some(c => c.includes('5-star') || c.includes('5 star') || c.includes('luxury') || c.includes('5-स्टार')) || title.includes('5 star') || content.includes('5 star');
        if (target === '4-star') return catList.some(c => c.includes('4-star') || c.includes('4 star') || c.includes('premium') || c.includes('4-स्टार')) || title.includes('4 star') || content.includes('4 star');
        if (target === '3-star') return catList.some(c => c.includes('3-star') || c.includes('3 star') || c.includes('comfort') || c.includes('3-स्टार')) || title.includes('3 star') || content.includes('3 star');
        if (target === 'budget') return catList.some(c => c.includes('budget') || c.includes('affordable') || c.includes('बजट')) || title.includes('budget') || content.includes('budget');
        return true;
      });
    }

    if (filtered.length === 0) {
      container.innerHTML = 
        '<div style="text-align:center; padding:60px 20px; background:#FFFFFF; border-radius:16px; border:1px solid #E2E8F0; margin:20px 0;">' +
          '<div style="font-size:48px; margin-bottom:12px;">🏨</div>' +
          '<h3 style="font-size:20px; font-weight:800; color:#0F172A; margin-bottom:8px;">New verified hotels &amp; camps coming soon!</h3>' +
          '<p style="color:#64748B; font-size:14px; max-width:500px; margin:0 auto 20px;">For immediate reservation quotes and priority bookings in this category, contact our 24/7 travel desk.</p>' +
          '<a href="https://wa.me/919079854982" target="_blank" style="display:inline-block; background:#25D366; color:#FFF; font-weight:700; padding:10px 22px; border-radius:24px; text-decoration:none;">💬 WhatsApp Concierge</a>' +
        '</div>';
      return;
    }

    let html = '<div class="post-grid" id="postGrid">';
    filtered.forEach((entry, idx) => {
      const title = (entry.title && entry.title.$t) || 'LexaTrip Luxury Stay';
      const content = (entry.content && entry.content.$t) || (entry.summary && entry.summary.$t) || '';
      const id = (entry.id && entry.id.$t) || ('post_' + idx);

      let postUrl = '#';
      if (entry.link) {
        const altLink = entry.link.find(l => l.rel === 'alternate');
        if (altLink) postUrl = altLink.href;
      }

      // Image extraction
      let imgUrl = 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?auto=format&fit=crop&w=800&q=80';
      if (entry.media$thumbnail && entry.media$thumbnail.url) {
        imgUrl = entry.media$thumbnail.url.replace('/s72-c/', '/s800/').replace('/w72-h72-p-k-no-nu/', '/w800-h1000-c/');
      } else {
        const m = content.match(/<img[^>]+src=['"]([^'"]+)['"]/i);
        if (m && m[1]) imgUrl = m[1];
      }

      // Category Tag
      let catLabel = 'Luxury Stay';
      if (entry.category && entry.category.length > 0) catLabel = entry.category[0].term;

      // Dynamic Realistic Discount
      const discountBadge = getPostDiscount(title, id);

      // Clean Snippet
      const tmp = document.createElement('div');
      tmp.innerHTML = content;
      const textOnly = (tmp.textContent || tmp.innerText || '').trim();
      const snippet = textOnly.slice(0, 110) + '...';

      html += 
        '<article class="post-card">' +
          '<div class="card-media-wrapper">' +
            '<span class="card-badge-cat">' + catLabel + '</span>' +
            '<span class="card-badge-discount">' + discountBadge + '</span>' +
            '<a href="' + postUrl + '">' +
              '<img alt="' + title.replace(/"/g, '&quot;') + '" class="card-media-img" loading="lazy" src="' + imgUrl + '"/>' +
            '</a>' +
          '</div>' +
          '<div class="card-body">' +
            '<h3 class="card-title"><a href="' + postUrl + '" style="color:inherit; text-decoration:none;">' + title + '</a></h3>' +
            '<p class="card-snippet">' + snippet + '</p>' +
            '<div class="card-actions">' +
              '<a class="card-btn card-btn-book" href="https://bookings.lexatrip.com/" target="_blank">🏨 Book Now</a>' +
              '<a class="card-btn card-btn-wa" href="https://wa.me/919079854982?text=' + encodeURIComponent('Hello LexaTrip, I would like to book: ' + title) + '" target="_blank">💬 WhatsApp</a>' +
            '</div>' +
          '</div>' +
        '</article>';
    });
    html += '</div>';

    container.innerHTML = html;
  }

  // Render Single Article with Interactive Booking Engine
  function renderSingleArticle(container, currentPath) {
    let matched = null;
    for (const entry of allPostsData) {
      if (entry.link) {
        const altLink = entry.link.find(l => l.rel === 'alternate');
        if (altLink && altLink.href && altLink.href.includes(currentPath)) {
          matched = entry;
          break;
        }
      }
    }

    const postTitle = matched ? ((matched.title && matched.title.$t) || '') : document.title;
    const postContent = matched ? ((matched.content && matched.content.$t) || '') : (document.querySelector('.post-body, .entry-content')?.innerHTML || '');
    const dynamicDiscount = getPostDiscount(postTitle, currentPath);

    container.innerHTML = 
      '<article class="article-container">' +
        '<span class="article-category">' + "RAJASTHAN Luxury Travel & Stays" + '</span>' +
        '<h1 class="article-title">' + postTitle + '</h1>' +
        '<div class="article-meta">' +
          '<div class="author-badge">' +
            '<div class="author-avatar">LT</div>' +
            '<span>LexaTrip™ Verified Concierge</span>' +
          '</div>' +
          '<span>•</span>' +
          '<span>⭐ Verified 5.0 Rating</span>' +
          '<span>•</span>' +
          '<span style="color:#FF6B00; font-weight:800;">⚡ ' + dynamicDiscount + ' Available</span>' +
        '</div>' +

        // Interactive Booking Engine Card
        '<div class="booking-engine-box">' +
          '<div class="booking-box-header">' +
            '<div class="booking-box-title">' +
              '<span>📅</span> Reserve Tour &amp; Check Availability' +
            '</div>' +
            '<span class="booking-box-tag">' + dynamicDiscount + '</span>' +
          '</div>' +
          '<div class="booking-fields-grid">' +
            '<div class="booking-field">' +
              '<label>Check-in Date</label>' +
              '<input id="bookCheckIn" type="date"/>' +
            '</div>' +
            '<div class="booking-field">' +
              '<label>Check-out Date</label>' +
              '<input id="bookCheckOut" type="date"/>' +
            '</div>' +
            '<div class="booking-field">' +
              '<label>Guests (Pax)</label>' +
              '<select id="bookPax">' +
                '<option value="1 Adult">1 Guest (Solo)</option>' +
                '<option selected="selected" value="2 Adults">2 Guests (Couple)</option>' +
                '<option value="3 Guests">3 Guests</option>' +
                '<option value="4 Guests (Family)">4 Guests (Family)</option>' +
                '<option value="5+ Guests (Group)">5+ Guests (Group)</option>' +
              '</select>' +
            '</div>' +
            '<div class="booking-field">' +
              '<label>Room / Camp Category</label>' +
              '<select id="bookRoomType">' +
                '<option value="Luxury Royal Camp">Luxury Royal Camp (AC/Heater)</option>' +
                '<option value="5-Star Palace Suite">5-Star Palace Suite</option>' +
                '<option value="4-Star Heritage Room">4-Star Heritage Room</option>' +
                '<option value="3-Star Deluxe Room">3-Star Deluxe Room</option>' +
                '<option value="Budget Friendly Room">Budget Friendly Stay</option>' +
              '</select>' +
            '</div>' +
          '</div>' +
          '<div class="booking-engine-actions">' +
            '<a class="engine-btn engine-btn-book" href="https://bookings.lexatrip.com/" onclick="triggerDirectBooking(event, '' + postTitle.replace(/'/g, '\\'') + '')">' +
              '<span>🏨 Instant Online Booking</span>' +
            '</a>' +
            '<a class="engine-btn engine-btn-wa" href="#" onclick="triggerWhatsAppBooking(event, '' + postTitle.replace(/'/g, '\\'') + '')">' +
              '<span>💬 Get Instant WhatsApp Quote</span>' +
            '</a>' +
          '</div>' +
        '</div>' +

        '<div class="article-content" style="font-size:16px; line-height:1.8;">' +
          postContent +
        '</div>' +

        '<div style="margin-top:40px; padding-top:24px; border-top:1px solid #E2E8F0; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">' +
          '<a href="/" style="display:inline-block; background:#0F172A; color:#FFFFFF; font-weight:700; padding:10px 22px; border-radius:30px; text-decoration:none;">← Back to All Stays</a>' +
          '<a href="https://bookings.lexatrip.com/" target="_blank" style="display:inline-block; background:#FF6B00; color:#FFFFFF; font-weight:700; padding:10px 22px; border-radius:30px; text-decoration:none;">Explore More Destinations →</a>' +
        '</div>' +
      '</article>';

    // Set default check-in/out dates
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const inEl = document.getElementById('bookCheckIn');
    const outEl = document.getElementById('bookCheckOut');
    if (inEl) inEl.value = today.toISOString().split('T')[0];
    if (outEl) outEl.value = tomorrow.toISOString().split('T')[0];
  }

  // Direct Online Booking Trigger
  function triggerDirectBooking(event, title) {
    if (event) event.preventDefault();
    const checkIn = document.getElementById('bookCheckIn')?.value || '';
    const checkOut = document.getElementById('bookCheckOut')?.value || '';
    const pax = document.getElementById('bookPax')?.value || '2 Adults';
    const roomType = document.getElementById('bookRoomType')?.value || 'Luxury Camp';

    const params = new URLSearchParams({
      dest: "RAJASTHAN",
      hotel: title,
      checkIn: checkIn,
      checkOut: checkOut,
      pax: pax,
      category: roomType,
      coupon: 'LEXA50ACTIVE'
    });
    window.open('https://bookings.lexatrip.com/?' + params.toString(), '_blank');
  }

  // Instant WhatsApp Quote Trigger
  function triggerWhatsAppBooking(event, title) {
    if (event) event.preventDefault();
    const checkIn = document.getElementById('bookCheckIn')?.value || '';
    const checkOut = document.getElementById('bookCheckOut')?.value || '';
    const pax = document.getElementById('bookPax')?.value || '2 Adults';
    const roomType = document.getElementById('bookRoomType')?.value || 'Luxury Camp';

    const waText = encodeURIComponent(
      'Hello LexaTrip Concierge! 🏨✨\n\n' +
      'I would like to book a verified stay in ' + "RAJASTHAN" + ':\n\n' +
      '📍 Hotel/Camp: ' + (title || 'Tour & Stay') + '\n' +
      '🛏️ Category: ' + roomType + '\n' +
      '📅 Check-in: ' + (checkIn || 'Earliest') + '\n' +
      '📅 Check-out: ' + (checkOut || 'Next Day') + '\n' +
      '👥 Number of Guests: ' + pax + '\n' +
      '🏷️ Promo Code: LEXAACTIVE\n\n' +
      'Please confirm availability and the best discounted quotation!'
    );
    window.open('https://wa.me/919079854982?text=' + waText, '_blank');
  }

  // Render Legal / Static Page
  function renderLegalStaticPage(container, title, content) {
    container.innerHTML = 
      '<article class="article-container">' +
        '<span class="article-category">LexaTrip™ Official Verified Page</span>' +
        '<h1 class="article-title">' + title + '</h1>' +
        '<div class="article-meta">' +
          '<div class="author-badge">' +
            '<div class="author-avatar">LT</div>' +
            '<span>LexaTrip Legal &amp; Compliance Team</span>' +
          '</div>' +
          '<span>•</span>' +
          '<span>📅 Updated: 2026</span>' +
          '<span>•</span>' +
          '<span>★ Verified Official Policy</span>' +
        '</div>' +
        '<div class="article-content" style="font-size:15px; line-height:1.8;">' +
          content +
        '</div>' +
        '<div style="margin-top:30px; padding-top:20px; border-top:1px solid #E2E8F0; text-align:center;">' +
          '<a href="/" style="display:inline-block; background:#0F172A; color:#FFFFFF; font-weight:700; padding:10px 24px; border-radius:30px; text-decoration:none;">← Back to Home</a>' +
        '</div>' +
      '</article>';
  }

  // Initialize on load
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', loadLexaBlogContent);
  } else {
    loadLexaBlogContent();
  }
